	@TriggerGuid = @TriggerGuid, 
	@ExpectedDate = @ExpectedDate, 
	@DescriptionOfWork = @DescriptionOfWork, 
	@Amount = @Amount, 
	@QuoteGuid = @QuoteGuid,
